export type AccessGrant = {
  roles: string[];
  contexts: string[];
  allContexts: boolean;
  buses: string[];
  allBuses: boolean;
};

export function decodeAccessGrant(r: Reader): AccessGrant {
  return {
    roles: readList16(r, (r) => readStr16(r)),
    contexts: readList16(r, (r) => readStr16(r)),
    allContexts: readBool(r),
    buses: readList16(r, (r) => readStr16(r)),
    allBuses: readBool(r),
  };
}

export function encodeAccessGrant(w: Writer, v: AccessGrant): void {
  writeLen16(w, v.roles.length, "AccessGrant.roles");
  for (const item0 of v.roles) {
    writeStr16(w, item0, "AccessGrant.roles");
  }
  writeLen16(w, v.contexts.length, "AccessGrant.contexts");
  for (const item0 of v.contexts) {
    writeStr16(w, item0, "AccessGrant.contexts");
  }
  writeU8(w, v.allContexts ? 1 : 0);
  writeLen16(w, v.buses.length, "AccessGrant.buses");
  for (const item0 of v.buses) {
    writeStr16(w, item0, "AccessGrant.buses");
  }
  writeU8(w, v.allBuses ? 1 : 0);
}

