/**
 * The follower must drop its log from `position` on. With a boundary, the
 * cut is right after the follower's last event record before `position`,
 * which must be the leader's: `prev_record_crc` is that event record's
 * stored CRC on the leader, or `prev_at_segment_start` says the leader has
 * no event before `position`. Control records are not compared: the follower
 * drops the ones that followed the event and the leader's follow in the
 * bytes that come next.
 */
export type TailTruncate = {
  epoch: bigint;
  position: bigint;
  hasBoundary: boolean;
  prevRecordCrc: number;
  prevAtSegmentStart: boolean;
};

export function decodeTailTruncate(r: Reader): TailTruncate {
  return {
    epoch: readU64(r),
    position: readU64(r),
    hasBoundary: readBool(r),
    prevRecordCrc: readU32(r),
    prevAtSegmentStart: readBool(r),
  };
}

export function encodeTailTruncate(w: Writer, v: TailTruncate): void {
  writeU64(w, v.epoch);
  writeU64(w, v.position);
  writeU8(w, v.hasBoundary ? 1 : 0);
  writeU32(w, v.prevRecordCrc);
  writeU8(w, v.prevAtSegmentStart ? 1 : 0);
}

